<?php
require_once __DIR__.'/../config/session.php';
require_once __DIR__.'/../config/auth.php';
require_once __DIR__.'/../config/helper.php';
require_once __DIR__.'/penilaian_override.php';
check_access([2]);$db=Database::getInstance();
$q=$db->prepare('SELECT id FROM guru WHERE user_id=?');$q->execute([$_SESSION['user_id']]);$guru=(int)$q->fetchColumn();
$q=$db->prepare('SELECT p.*,m.nama_mapel,k.nama_kelas FROM pengajaran p JOIN mapel m ON m.id=p.mapel_id JOIN kelas k ON k.id=p.kelas_id WHERE p.guru_id=? ORDER BY k.nama_kelas,m.nama_mapel,p.tahun_ajaran DESC');$q->execute([$guru]);$assignments=$q->fetchAll();
$pid=(int)($_GET['pengajaran_id']??($assignments[0]['id']??0));$info=null;foreach($assignments as $a)if((int)$a['id']===$pid)$info=$a;
if($pid&&!$info){http_response_code(403);exit('Pengajaran bukan milik Anda.');}
$components=[];$students=[];$scores=[];$automatic=[];
if($info){
 $q=$db->prepare('SELECT * FROM komponen_penilaian WHERE pengajaran_id=? ORDER BY urutan,id');$q->execute([$pid]);$components=$q->fetchAll();
 $q=$db->prepare('SELECT id,nis,nisn,nama_lengkap FROM siswa WHERE kelas_id=? ORDER BY nama_lengkap,id');$q->execute([$info['kelas_id']]);$students=$q->fetchAll();
 $q=$db->prepare('SELECT n.* FROM nilai_komponen n JOIN komponen_penilaian k ON k.id=n.komponen_id WHERE k.pengajaran_id=?');$q->execute([$pid]);foreach($q->fetchAll() as $n)$scores[$n['siswa_id']][$n['komponen_id']]=$n['nilai'];
 foreach($students as $s)$automatic[$s['id']]=po_automatic($db,$pid,(int)$s['id']);
}
$weight=array_sum(array_column($components,'bobot'));$ready=abs($weight-100)<.001;
$success=$_SESSION['flash_success']??'';$error=$_SESSION['flash_error']??'';unset($_SESSION['flash_success'],$_SESSION['flash_error']);
require_once __DIR__.'/header.php';require_once __DIR__.'/sidebar.php';
$hidden=static function(string $action)use($pid):void{echo '<input type="hidden" name="csrf_token" value="'.sanitize($_SESSION['csrf_token']).'"><input type="hidden" name="pengajaran_id" value="'.$pid.'"><input type="hidden" name="action" value="'.sanitize($action).'">';};
?>
<link rel="stylesheet" href="../assets/css/nilai-manual.css?v=1">
<div id="page-content-wrapper" class="nm-page"><nav class="navbar top-navbar px-4 py-3"><div><h1 class="h5 fw-bold mb-1">Rekap Nilai</h1><small class="text-muted">Rata-rata tugas, ulangan harian, dan nilai akhir berdasarkan bobot.</small></div><a class="btn btn-outline-primary" href="nilai_manual.php?pengajaran_id=<?= $pid ?>">Input Nilai Manual</a></nav><main class="nm-content p-3 p-md-4">
<?php if($success): ?><div class="alert alert-success"><?= sanitize($success) ?></div><?php endif ?><?php if($error): ?><div class="alert alert-danger"><?= sanitize($error) ?></div><?php endif ?>
<form method="get" class="nm-card p-4 mb-4"><label for="rekapPengajaranNilai" class="form-label fw-semibold">Mata pelajaran dan kelas</label><select id="rekapPengajaranNilai" name="pengajaran_id" class="form-select" onchange="this.form.submit()"><option value="">Pilih kelas</option><?php foreach($assignments as $a): ?><option value="<?= (int)$a['id'] ?>" <?= (int)$a['id']===$pid?'selected':'' ?>><?= sanitize($a['nama_mapel'].' — '.$a['nama_kelas'].' ('.$a['semester'].', '.$a['tahun_ajaran'].')') ?></option><?php endforeach ?></select></form>
<?php if($info): ?>
<div class="alert alert-info small">Tugas Harian mengikuti nilai tugas lewat tenggat dan nilai manual lama yang masih tersimpan. Tugas yang sudah dikumpulkan tetapi belum dinilai tidak dirata-ratakan; tugas lewat tenggat yang tidak dikumpulkan bernilai 0. Ulangan Harian mengikuti ujian yang jadwalnya sudah berakhir. Nilai pengganti manual tetap berlaku sampai dikembalikan ke otomatis.</div>
<details class="nm-card p-4 mb-4"><summary class="fw-semibold">Komponen dan bobot penilaian (<?= sanitize((string)$weight) ?>%)</summary><div class="table-responsive mt-3"><table class="table"><thead><tr><th>Komponen</th><th>Bobot (%)</th><th>Aksi</th></tr></thead><tbody><?php foreach($components as $c): ?><tr><td colspan="3"><form class="d-flex flex-wrap gap-2 align-items-center" method="post" action="rekap_nilai_action.php"><?php $hidden('update'); ?><input type="hidden" name="id" value="<?= (int)$c['id'] ?>"><input type="hidden" name="nama_komponen" value="<?= sanitize($c['nama_komponen']) ?>"><strong class="me-auto"><?= sanitize($c['nama_komponen']) ?></strong><input type="number" name="bobot" min="0.01" max="100" step="0.01" class="form-control nm-score" aria-label="Bobot <?= sanitize($c['nama_komponen']) ?>" value="<?= sanitize((string)$c['bobot']) ?>" required><button class="btn btn-outline-primary btn-sm">Simpan Bobot</button></form></td></tr><?php endforeach ?></tbody></table></div><form class="d-flex flex-wrap gap-2 mt-3" method="post" action="rekap_nilai_action.php"><?php $hidden('add'); ?><select name="nama_komponen" class="form-select nm-upload" aria-label="Komponen baru" required><?php foreach(['Tugas Harian','Ulangan Harian','Kehadiran','UTS','UAS','Ujian Praktik'] as $name): if(in_array($name,array_column($components,'nama_komponen'),true))continue; ?><option><?= sanitize($name) ?></option><?php endforeach ?></select><input name="bobot" type="number" min="0.01" max="100" step="0.01" placeholder="Bobot %" aria-label="Bobot komponen baru" class="form-control nm-score" required><button class="btn btn-primary">Tambah Komponen</button></form></details>
<?php if(!$ready): ?><div class="alert alert-warning">Total bobot harus 100% untuk menyimpan nilai komponen dan menampilkan nilai akhir.</div><?php endif ?>
<div class="d-flex flex-wrap gap-2 mb-3"><a class="btn btn-outline-primary btn-sm" href="tugas.php?rekap_pengajaran=<?= $pid ?>#rekap-tugas">Rekap Tugas</a><a class="btn btn-outline-primary btn-sm" href="nilai_manual.php?pengajaran_id=<?= $pid ?>&amp;jenis=ujian">Riwayat Ujian Harian</a><a class="btn btn-outline-success btn-sm" href="rekap_nilai_import.php?pengajaran_id=<?= $pid ?>">Impor Komponen / UTS / UAS</a><?php if($ready): ?><a class="btn btn-outline-success btn-sm" href="rekap_action.php?action=export_excel&amp;pengajaran_id=<?= $pid ?>">Unduh Excel</a><a class="btn btn-outline-secondary btn-sm" href="rekap_action.php?action=export_pdf&amp;pengajaran_id=<?= $pid ?>">Unduh PDF</a><?php endif ?></div>
<section class="nm-card"><form method="post" action="rekap_nilai_action.php"><?php $hidden('save_scores'); ?><div class="table-responsive"><table class="table align-middle mb-0"><thead class="table-light"><tr><th>Siswa</th><?php foreach($components as $c): ?><th><?= sanitize($c['nama_komponen']) ?><small class="d-block"><?= sanitize((string)$c['bobot']) ?>%</small></th><?php endforeach ?><th>Nilai Akhir</th></tr></thead><tbody><?php foreach($students as $s):$total=0;$complete=true; ?><tr><td class="text-nowrap"><?= sanitize($s['nama_lengkap']) ?></td><?php foreach($components as $c):$auto=$automatic[$s['id']][$c['nama_komponen']]??null;$override=isset($scores[$s['id']][$c['id']]);$value=$override?(float)$scores[$s['id']][$c['id']]:$auto;if($value===null)$complete=false;else $total+=$value*(float)$c['bobot']/100;$manual=$auto===null||$override; ?><td data-auto="<?= $auto!==null?number_format($auto,2,'.',''):'' ?>"><input type="hidden" class="score-source" name="sumber[<?= (int)$s['id'] ?>][<?= (int)$c['id'] ?>]" value="<?= $manual?'manual':'auto' ?>"><input class="form-control nm-score score-input" type="number" min="0" max="100" step="0.01" name="nilai[<?= (int)$s['id'] ?>][<?= (int)$c['id'] ?>]" aria-label="<?= sanitize($c['nama_komponen'].' '.$s['nama_lengkap']) ?>" value="<?= $value!==null?number_format($value,2,'.',''):'' ?>" <?= !$manual?'disabled':'' ?>><?php if($auto!==null): ?><span class="score-label small text-muted d-block mt-1"><?= $manual?'Manual':'Otomatis' ?></span><button type="button" class="score-toggle btn btn-link btn-sm px-0" aria-pressed="<?= $manual?'true':'false' ?>"><?= $manual?'Kembali ke Otomatis':'Isi Manual' ?></button><?php endif ?></td><?php endforeach ?><td><strong><?= $ready?($complete?number_format($total,2):'Belum lengkap'):'Bobot belum 100%' ?></strong></td></tr><?php endforeach ?></tbody></table></div><div class="p-3 text-end border-top"><button class="btn btn-primary" <?= !$ready||!$students?'disabled':'' ?>>Simpan Nilai Komponen</button></div></form></section>
<?php endif ?></main></div>
